  "inlineSchema": "// =============================================================================\n// FILE: prisma/schema.prisma\n// Cyber Community Pakistan — content database (Supabase Postgres, Prisma 7)\n//\n// Two kinds of content:\n//  1. Lists editors add / remove / reorder → real tables\n//     (menu, socials, footer links, programs, events, testimonials, FAQs, team)\n//  2. Section copy (headlines, taglines, small lists) → `Section` rows, one per\n//     section key, content stored as JSON and validated with zod\n//     (see lib/content/schemas.ts for every key and its fields)\n// =============================================================================\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../lib/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ---------- Global settings (single row, id = 1) ------------------------------\n\nmodel SiteSettings {\n  id        Int    @id @default(1)\n  name      String\n  shortName String\n  email     String\n  /// Ambassador application form (used by many buttons)\n  applyUrl  String\n\n  // Optional image logo (Cloudinary URL or /public path). Null = text mark.\n  logoUrl           String?\n  logoPublicId      String? /// Cloudinary public_id (for replacing/deleting)\n  logoAlt           String?\n  logoWidth         Int?\n  logoHeight        Int?\n  logoDisplayHeight Int     @default(34)\n  /// true = logo inverts like the header text (white logos); false = keep colours\n  logoBlend         Boolean @default(true)\n\n  updatedAt DateTime @updatedAt\n}\n\n// ---------- Navigation ---------------------------------------------------------\n\n/// Full-screen menu. Top-level items have parentId = null; dropdown links have a parent.\nmodel MenuItem {\n  id          String     @id @default(cuid())\n  label       String\n  href        String? /// '#section', '/page', '/page#section', 'https://…', 'mailto:…'\n  description String?\n  badge       String?\n  order       Int        @default(0)\n  visible     Boolean    @default(true)\n  parentId    String?\n  parent      MenuItem?  @relation(\"MenuTree\", fields: [parentId], references: [id], onDelete: Cascade)\n  children    MenuItem[] @relation(\"MenuTree\")\n  createdAt   DateTime   @default(now())\n  updatedAt   DateTime   @updatedAt\n\n  @@index([parentId, order])\n}\n\nmodel SocialLink {\n  id        String   @id @default(cuid())\n  label     String\n  href      String\n  order     Int      @default(0)\n  visible   Boolean  @default(true)\n  updatedAt DateTime @updatedAt\n}\n\nmodel FooterLink {\n  id        String   @id @default(cuid())\n  label     String\n  href      String\n  order     Int      @default(0)\n  visible   Boolean  @default(true)\n  updatedAt DateTime @updatedAt\n}\n\n// ---------- Section copy ---------------------------------------------------------\n\n/// One row per section, e.g. key = \"home.hero\". `content` shape is defined in\n/// lib/content/schemas.ts and validated on read and on save.\nmodel Section {\n  key       String   @id\n  content   Json\n  updatedAt DateTime @updatedAt\n}\n\n// ---------- Home: programs -------------------------------------------------------\n\nenum ProgramStatus {\n  OPEN\n  COMING_SOON\n  ALWAYS_ON\n}\n\nenum ProgramArt {\n  TERMINAL\n  LAB\n  MIC\n  BADGE\n  SHIELD\n}\n\nmodel Program {\n  id          String        @id @default(cuid())\n  title       String\n  level       String\n  status      ProgramStatus @default(OPEN)\n  description String\n  meta        String[]\n  ctaLabel    String\n  ctaHref     String\n  art         ProgramArt    @default(TERMINAL)\n  featured    Boolean       @default(false)\n  order       Int           @default(0)\n  published   Boolean       @default(true)\n  createdAt   DateTime      @default(now())\n  updatedAt   DateTime      @updatedAt\n\n  @@index([published, order])\n}\n\n// ---------- Home: events ----------------------------------------------------------\n\nenum EventType {\n  LECTURE\n  WORKSHOP\n  WEBINAR\n  MEETUP\n}\n\nmodel Event {\n  id          String    @id @default(cuid())\n  /// Calendar day (Pakistan time). Past events drop off the home page automatically.\n  date        DateTime  @db.Date\n  title       String\n  type        EventType @default(LECTURE)\n  series      String?\n  format      String\n  description String\n  href        String\n  published   Boolean   @default(true)\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  @@index([published, date])\n}\n\n// ---------- Home: testimonials & FAQ ------------------------------------------------\n\nmodel Testimonial {\n  id        String   @id @default(cuid())\n  quote     String\n  name      String\n  role      String\n  avatarUrl String?\n  /// true = sample text (shows a \"Sample\" tag on the site)\n  isSample  Boolean  @default(false)\n  order     Int      @default(0)\n  published Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([published, order])\n}\n\nmodel Faq {\n  id        String   @id @default(cuid())\n  question  String\n  answer    String\n  order     Int      @default(0)\n  published Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([published, order])\n}\n\n// ---------- About: team -----------------------------------------------------------\n\nenum TeamGroup {\n  CORE\n  LEADS\n  ADVISORS\n}\n\nmodel TeamMember {\n  id            String    @id @default(cuid())\n  name          String\n  role          String\n  group         TeamGroup @default(CORE)\n  city          String?\n  photoUrl      String?\n  photoPublicId String? /// Cloudinary public_id\n  linkedin      String?\n  x             String?\n  github        String?\n  email         String?\n  order         Int       @default(0)\n  published     Boolean   @default(true)\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  @@index([published, order])\n}\n\n// ---------- Admin access (Supabase Auth) -------------------------------------------\n\nenum AdminRole {\n  OWNER\n  EDITOR\n}\n\n/// People allowed into /admin. `id` = Supabase Auth user id (auth.users.id).\nmodel AdminUser {\n  id        String    @id @db.Uuid\n  email     String    @unique\n  name      String?\n  role      AdminRole @default(EDITOR)\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n}\n",
